  ('MMR-AF-162','Maruti Baleno Waterproof Body Cover','Exterior','Maruti Suzuki Baleno demo fitment. Confirm year, body dimensions, and mirror pockets. Illustrative image; demo price/stock only.',1795,array['Maruti Suzuki','Baleno','body cover'],74,'https://images.pexels.com/photos/36903243/pexels-photo-36903243.jpeg?auto=compress&cs=tinysrgb&w=1200','https://www.autofurnish.com/collections/car-accessories','Maruti Suzuki','Baleno'),
  ('MMR-AF-163','Toyota Innova Crysta 3-Row Mat Set','Interior','Toyota Innova Crysta demo fitment. Confirm year, row layout, and seat configuration. Illustrative image; demo price/stock only.',6290,array['Toyota','Innova Crysta','floor mats','3 row'],79,'/images/products/ford-ecosport-floor-mats.png','https://www.autofurnish.com/collections/car-foot-mats','Toyota','Innova Crysta'),
  ('MMR-AF-164','Kia Sonet Custom Floor Mat Set','Interior','Kia Sonet demo fitment. Confirm generation and floor layout. Illustrative image; demo price/stock only.',5390,array['Kia','Sonet','floor mats'],76,'/images/products/ford-ecosport-floor-mats.png','https://www.autofurnish.com/collections/car-foot-mats','Kia','Sonet')
), upserted as (
  insert into public.products(sku,name,category_id,brand_id,description,price,tags,popularity,status,in_stock,image,source_url)
  select l.sku,l.name,c.id,b.id,l.description,l.price,l.tags,l.popularity,'active',true,l.image,l.source_url
  from listing l join public.categories c on c.name=l.category join public.brands b on b.slug='autofurnish'
  on conflict(sku) do update set name=excluded.name,category_id=excluded.category_id,brand_id=excluded.brand_id,
    description=excluded.description,price=excluded.price,tags=excluded.tags,popularity=excluded.popularity,
    status='active',deleted_at=null,image=excluded.image,source_url=excluded.source_url
  returning id,sku
)
insert into public.inventory(product_id,quantity,low_stock_threshold)
select id,10,3 from upserted
on conflict(product_id) do update set low_stock_threshold=excluded.low_stock_threshold,updated_at=now();

-- Model-specific rows only link to matching India-market make/model records.
with fitment(sku,make,model) as (values
  ('MMR-AF-140','Ford','EcoSport'),('MMR-AF-141','Ford','EcoSport'),('MMR-AF-142','Ford','EcoSport'),('MMR-AF-143','Ford','EcoSport'),('MMR-AF-144','Ford','EcoSport'),
  ('MMR-AF-145','Ford','Figo'),('MMR-AF-146','Ford','Figo'),('MMR-AF-147','Ford','Figo'),('MMR-AF-148','Ford','Endeavour'),('MMR-AF-149','Ford','Endeavour'),('MMR-AF-150','Ford','Mustang'),
  ('MMR-AF-151','Mahindra','XUV 3XO'),('MMR-AF-152','Mahindra','XUV 3XO'),('MMR-AF-153','Mahindra','XUV 3XO'),('MMR-AF-154','Mahindra','Thar'),('MMR-AF-155','Mahindra','Thar'),
  ('MMR-AF-156','Tata','Nexon'),('MMR-AF-157','Tata','Nexon'),('MMR-AF-158','Tata','Punch EV'),('MMR-AF-159','Hyundai','Creta'),('MMR-AF-160','Hyundai','Creta'),
  ('MMR-AF-161','Maruti Suzuki','Swift'),('MMR-AF-162','Maruti Suzuki','Baleno'),('MMR-AF-163','Toyota','Innova Crysta'),('MMR-AF-164','Kia','Sonet')
)
insert into public.product_compatibility(product_id,vehicle_id,notes)
select p.id,v.id,'Demo fitment reference; verify exact generation, trim, and dimensions with supplier.'
from fitment f join public.products p on p.sku=f.sku
join public.vehicles v on v.make=f.make and v.model=f.model
on conflict(product_id,vehicle_id) do update set notes=excluded.notes;

-- Apply broad universal fitment records only to the 25 universal demo listings.
insert into public.product_compatibility(product_id,vehicle_id,notes)
select p.id,v.id,'Universal accessory demo; confirm dimensions and installation requirements.'
from public.products p cross join public.vehicles v
where p.sku between 'MMR-AF-115' and 'MMR-AF-139'
on conflict(product_id,vehicle_id) do update set notes=excluded.notes;

commit;
